cat > $TMPDIR/lint.py <<'EOF'
import ast, sys, builtins, glob, re
known_attrs=set()
for t in (set, frozenset, dict, list, str, bytes, tuple, int, float, object, type(open), __import__('io').BytesIO, __import__('socket').socket, __import__('datetime').datetime, __import__('datetime').timedelta, __import__('collections').deque):
    known_attrs|=set(dir(t))
files=sorted(glob.glob('boltons/*.py'))
defined_attrs=set()
for f in files:
    tree=ast.parse(open(f).read())
    for n in ast.walk(tree):
        if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)): defined_attrs.add(n.name)
        if isinstance(n,ast.Attribute) and isinstance(n.ctx,ast.Store): defined_attrs.add(n.attr)
        if isinstance(n,ast.Name) and isinstance(n.ctx,ast.Store): defined_attrs.add(n.id)
        if isinstance(n,ast.alias): defined_attrs.add(n.asname or n.name.split('.')[0])
import importlib, pkgutil
mods=set()
for m in ['os','sys','re','io','socket','itertools','functools','collections','math','time','datetime','inspect','traceback','linecache','mailbox','tempfile','shutil','errno','fnmatch','json','gzip','zlib','string','unicodedata','heapq','bisect','operator','weakref','gc','random','hashlib','uuid','binascii','codecs','pdb','signal','platform','locale','getpass','struct','threading','warnings','types','abc','copy','pprint','html','keyword','textwrap','stat','contextlib','calendar','decimal','fractions','statistics','reprlib','ssl','sysconfig','subprocess','array','html.parser','collections.abc','urllib','urllib.parse','numbers','enum','typing','pathlib','glob','pickle','marshal','ctypes','dis']:
    try: known_attrs|=set(dir(importlib.import_module(m)))
    except Exception: pass
sys.path.insert(0,'.')
for f in files:
    try: known_attrs|=set(dir(importlib.import_module('boltons.'+f[8:-3])))
    except Exception: pass
for f in files:
    src=open(f).read(); tree=ast.parse(src)
    for n in ast.walk(tree):
        if isinstance(n,ast.Attribute) and isinstance(n.ctx,ast.Load):
            a=n.attr
            if a not in known_attrs and a not in defined_attrs and not a.startswith('__'):
                print(f"{f}:{n.lineno}: attr .{a}")
    # undefined names (crude): loaded names never bound anywhere in module
    bound=set(dir(builtins))
    for n in ast.walk(tree):
        if isinstance(n,ast.Name) and not isinstance(n.ctx,ast.Load): bound.add(n.id)
        elif isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)): bound.add(n.name)
        elif isinstance(n,ast.arg): bound.add(n.arg)
        elif isinstance(n,ast.alias): bound.add((n.asname or n.name).split('.')[0])
        elif isinstance(n,ast.ExceptHandler) and n.name: bound.add(n.name)
    for n in ast.walk(tree):
        if isinstance(n,ast.Name) and isinstance(n.ctx,ast.Load) and n.id not in bound:
            print(f"{f}:{n.lineno}: name {n.id}")
EOF
python3 $TMPDIR/lint.py 2>&1 | grep -v easterutils | head -60

